s1-reverse-an-array.code:
void reverseArray(vector<int>& a) {
    int left = 0, right = static_cast<int>(a.size()) - 1;
    while (left < right) swap(a[left++], a[right--]);
}

s1-check-if-a-string-is-palindrome-or-no.code:
bool isPalindromeString(const string& s) {
    int left = 0, right = static_cast<int>(s.size()) - 1;
    while (left < right) {
        if (s[left] != s[right]) return false;
        ++left;
        --right;
    }
    return true;
}

s1-fibonacci-number.code:
long long fibonacci(int n) {
    if (n < 0 || n > 92) throw out_of_range("n must be in [0, 92]");
    if (n == 0) return 0;
    long long prev = 0, curr = 1;
    for (int i = 2; i <= n; ++i) {
        long long next = prev + curr;
        prev = curr;
        curr = next;
    }
    return curr;
}

s1-find-the-highest-lowest-frequency-ele.code:
pair<int, int> highestLowestFrequency(const vector<int>& a) {
    if (a.empty()) throw invalid_argument("array must be nonempty");
    unordered_map<int, int> freq;
    for (int x : a) ++freq[x];
    int high = a[0], low = a[0];
    for (const auto& [value, count] : freq) {
        if (count > freq[high] || (count == freq[high] && value < high))
            high = value;
        if (count < freq[low] || (count == freq[low] && value < low))
            low = value;
    }
    return {high, low};
}
